    if (getStaffPermissions()?.pos_access?.OperationManagement?.ItemsManagement?.edit_item === false) {
      toast.error("You do not have permission to delete items.");
      return;
    }
    if (!window.confirm(`Are you sure you want to delete "${itemName}"?`)) return;
    try {
      if (navigator.onLine && !String(itemId).startsWith('L-')) {
        await posService.deleteMenuItem(itemId);
      } else if (!String(itemId).startsWith('L-')) {
        const deletedQueue = JSON.parse(localStorage.getItem('pos_deleted_items_queue') || '[]');
        deletedQueue.push(itemId);
        localStorage.setItem('pos_deleted_items_queue', JSON.stringify(deletedQueue));
      }

      setItemMgmtItems(prev => {
        const nextItems = prev.filter(i => i.id !== itemId);
        localStorage.setItem('pos_item_mgmt_items', JSON.stringify(nextItems));
        return nextItems;
      });

      if (!navigator.onLine) {
        setCatalog(prev => {
          const nextCatalog = prev.filter(item => item.id !== itemId);
          localStorage.setItem('pos_catalog_cache', JSON.stringify(nextCatalog));
          return nextCatalog;
        });
        toast.error("Offline Mode: Deleted Locally Only");
